contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newRecipient) public {
        require(newRecipient != address(0), "zero recipient not useful");

        // Read the state before the call
        address before = c.rewardsRecipient();

        // Make the deciding call, capturing whether it reverted
        bool reverted;
        try c.setRewardsRecipient(newRecipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the state after the call
        address afterRecipient = c.rewardsRecipient();

        // General rule: owner's call always sets the field to the argument;
        // non-owner's call must revert and leave the field unchanged.
        bool callerIsOwner = (msg.sender == c.owner());
        assert(
            (callerIsOwner && !reverted && afterRecipient == newRecipient) ||
            (!callerIsOwner && reverted && afterRecipient == before)
        );
    }
}

