contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to) public {
        // No precondition: any amount, any claim flag, any recipient are valid inputs.
        // Determine whether the caller has permission (operator or owner) and call.
        bool callerIsOperator = (msg.sender == c.operator());
        bool callerIsOwner = (msg.sender == c.owner());

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call reverts if and only if the caller is neither
        // the operator nor the owner. The revert reason must be NotOperatorOrOwner.
        assert(reverted == !(callerIsOperator || callerIsOwner));
    }
}

