contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint32 pId, address token, address rewards) public payable {
        // Configure c to use the rewards pool we choose.
        c.setCvxPoolInfo(pId, token, rewards);

        // Read the configured rewards address via the public getter of cvxPoolInfo.
        (, , address configuredRewards) = c.cvxPoolInfo();

        // Only the rule for a non-zero, contract rewards address is meaningful;
        // when rewards is not a contract, earned() reverts, which the checker
        // can explore separately. Here we constrain to the contract case.
        require(configuredRewards.code.length > 0, "rewards not a contract");

        uint256 got = c.earned();
        uint256 expected = IBaseRewardPool(configuredRewards).earned(address(c));

        assert(got == expected);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint32 pId, address token, address rewards) public payable {
        // Precondition on parameters: the rewards pool must be a contract,
        // otherwise c.earned() will revert and there is no return value to compare.
        require(rewards.code.length > 0, "rewards not a contract");

        // Drive c through its public entry to configure the CVX pool info.
        c.setCvxPoolInfo(pId, token, rewards);

        // Read the configured rewards address through the public getter.
        (, , address configuredRewards) = c.cvxPoolInfo();

        // Deciding call: read c.earned() through the public surface.
        uint256 got = c.earned();

        // Expected value: what the configured rewards pool reports for c.
        uint256 expected = IBaseRewardPool(configuredRewards).earned(address(c));

        // General rule: c.earned() mirrors the rewards pool's earned(address(c)).
        assert(got == expected);
    }

    receive() external payable {}
}

