contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint256 stakedBefore = c.stakedBalance();
        uint256 earnedBefore = c.earned();

        (bool success, bytes memory data) = address(c).staticcall(
            abi.encodeWithSignature("showPositions()")
        );
        assert(!success || data.length >= 64);

        uint256 returnedStaked;
        uint256 returnedEarned;
        if (success) {
            (returnedStaked, returnedEarned) = abi.decode(data, (uint256, uint256));
        }

        assert(
            !success ||
            (returnedStaked == c.stakedBalance() && returnedEarned == c.earned())
        );
    }

    receive() external payable {}
}

