contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, uint256 amount) public payable {
        bool reverted;
        // We cannot change msg.sender of c calls, but the test contract's calls are always msg.sender == address(this).
        // The operator of c may or may not be address(this). We can read c.operator() and check consistency.
        address cOperator = c.operator();
        if (cOperator == address(this)) {
            // If this contract is operator, depositAndStake should not revert (assuming pool not shutdown and sufficient allowance/balance).
            // We cannot ensure pool shutdown status without reading isCvxShutdown(), but we can still check that if it succeeds, the payout logic is consistent.
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // General rule: if depositAndStake succeeds, the operator was the caller (address(this)).
            assert(reverted || cOperator == address(this));
        } else {
            // If this contract is not operator, depositAndStake must revert
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        }
    }

    receive() external payable {}
}

