contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to) public {
        // Only the owner (this contract) can call withdrawAndUnwrap; no additional precondition needed.
        // Read the before-balance of clpToken held by c.
        uint256 balBefore = IERC20(c.clpToken()).balanceOf(address(c));

        // Attempt the state-changing call and record whether it reverted.
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = IERC20(c.clpToken()).balanceOf(address(c));

        // General rule:
        // - If the call did not revert, then when `amount` <= pre-call internal balance, the balance decreased by exactly `amount`
        //   (or stayed the same if `to` was given but transfer succeeded and amount equals the full balance? No: safeTransfer always transfers `amount`,
        //   but if `amount` exceeds internal balance the contract must have unstaked the difference; the net balance change is always -amount on success).
        // - If the call reverted, it must be because the internal balance was insufficient and the external unstake call failed
        //   (i.e., `amount > balBefore`).  If `amount <= balBefore`, the call cannot revert under normal operation.
        if (reverted) {
            assert(amount > balBefore);
        } else {
            // On success the balance decreases by exactly `amount` (unchecked subtraction avoided by adding).
            assert(balAfter + amount == balBefore);
        }
    }
}

